svg.script:
function updateCard() {
  try {
    if (typeof fetch !== 'undefined') {
      fetch('https://api.github.com/users/sanguirIS')
        .then(function(r){ return r.json(); })
        .then(function(user){
          var r = document.getElementById('repos-num');
          if (r) r.textContent = ' ' + (user.public_repos !== undefined ? user.public_repos : r.textContent.trim());
          var f = document.getElementById('followers-num');
          if (f) f.textContent = ' ' + (user.followers !== undefined ? user.followers : f.textContent.trim());
        });
      fetch('https://api.github.com/users/sanguirIS/repos?per_page=100')
        .then(function(r){ return r.json(); })
        .then(function(repos){
          var total = repos.reduce(function(s, repo){ return s + (repo.stargazers_count || 0); }, 0);
          var s = document.getElementById('stars-num');
          if (s) s.textContent = ' ' + total;
        });
    }
  } catch (e) {}
}
if (document.readyState === 'complete' || document.readyState === 'interactive') updateCard();
else if (window.addEventListener) window.addEventListener('load', updateCard);
else if (window.attachEvent) window.attachEvent('onload', updateCard);
